import { createChart, removeChart } from '../test/ut/core/utHelper';

describe('aria role="img"', function () {
    it('sets role="img" together with aria-label on the chart container', function () {
        const chart = createChart();
        chart.setOption({
            aria: {
                enabled: true
            },
            xAxis: { type: 'category', data: ['a', 'b'] },
            yAxis: {},
            series: [{ type: 'bar', data: [1, 2] }]
        });
        const dom = chart.getDom();
        expect(dom.getAttribute('role')).toEqual('img');
        expect(dom.getAttribute('aria-label')).toBeTruthy();
        removeChart(chart);
    });
});

